Fecha de script: 9/05/2026 6:10:49 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_CrearCategoria]\r\n(\r\n    @CategoryName NVARCHAR(100),\r\n    @Description NVARCHAR(500) = NULL,\r\n    @Picture NVARCHAR(MAX) = NULL\r\n)\r\nAS\r\nBEGIN\r\n\r\n    SET NOCOUNT ON;\r\n\r\n    INSERT INTO Categories\r\n    (\r\n        CategoryName,\r\n        Description,\r\n        Picture\r\n    )\r\n    VALUES\r\n    (\r\n        @CategoryName,\r\n        @Description,\r\n        @Picture\r\n    );\r\n\r\n        SELECT SCOPE_IDENTITY() AS CategoryID;\r\n\r\n\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_CrearCategoria' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_CrearProducto]"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_CrearProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: StoredProcedure [dbo].[sp_CrearProducto] Fecha de script: 9/05/2026 6:10:49 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_CrearProducto]\r\n(\r\n    @ProductName NVARCHAR(200),\r\n    @SupplierID INT = NULL,\r\n    @CategoryID INT,\r\n    @QuantityPerUnit NVARCHAR(100) = NULL,\r\n    @UnitPrice DECIMAL(18,2) = NULL,\r\n    @UnitsInStock INT = NULL,\r\n    @UnitsOnOrder INT = NULL,\r\n    @ReorderLevel INT = NULL,\r\n    @Discontinued BIT\r\n)\r\nAS\r\nBEGIN\r\n\r\n    SET NOCOUNT ON;\r\n\r\n    INSERT INTO Products\r\n    (\r\n        ProductName,\r\n        SupplierID,\r\n        CategoryID,\r\n        QuantityPerUnit,\r\n        UnitPrice,\r\n        UnitsInStock,\r\n        UnitsOnOrder,\r\n        ReorderLevel,\r\n        Discontinued\r\n    )\r\n    VALUES\r\n    (\r\n        @ProductName,\r\n        @SupplierID,\r\n        @CategoryID,\r\n        @QuantityPerUnit,\r\n        @UnitPrice,\r\n        @UnitsInStock,\r\n        @UnitsOnOrder,\r\n        @ReorderLevel,\r\n        @Discontinued\r\n    );\r\n\r\n    SELECT SCOPE_IDENTITY() AS ProductID;\r\n\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_CrearProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_EliminarProducto]"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_EliminarProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: StoredProcedure [dbo].[sp_EliminarProducto] Fecha de script: 9/05/2026 6:10:49 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_EliminarProducto]\r\n(\r\n    @ProductID INT\r\n)\r\nAS\r\nBEGIN\r\n\r\n    SET NOCOUNT ON;\r\n\r\n    DELETE FROM Products\r\n    WHERE ProductID = @ProductID\r\n\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_EliminarProducto' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_GetUser]"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_GetUser' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: StoredProcedure [dbo].[sp_GetUser] Fecha de script: 9/05/2026 6:10:49 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_GetUser]\r\n    @Username NVARCHAR(100),\r\n    @PasswordHash NVARCHAR(500)\r\nAS\r\nBEGIN\r\n\r\n    SELECT\r\n        Id,\r\n        Username\r\n    FROM Users\r\n    WHERE Username = @Username\r\n    AND PasswordHash = @PasswordHash\r\n\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_GetUser' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ListadoProductos]"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_ListadoProductos' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: StoredProcedure [dbo].[sp_ListadoProductos] Fecha de script: 9/05/2026 6:10:49 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_ListadoProductos]\r\n(\r\n    @ProductName NVARCHAR(200) = NULL,\r\n    @CategoryName NVARCHAR(100) = NULL,\r\n    @SupplierID INT = NULL,\r\n    @Discontinued BIT = NULL,\r\n\r\n    @PageNumber INT = 1,\r\n    @PageSize INT = 10\r\n)\r\nAS\r\nBEGIN\r\n\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        p.ProductID,\r\n        p.ProductName,\r\n        p.SupplierID,\r\n        p.CategoryID,\r\n        c.CategoryName,\r\n        p.QuantityPerUnit,\r\n        p.UnitPrice,\r\n        p.UnitsInStock,\r\n        p.UnitsOnOrder,\r\n        p.ReorderLevel,\r\n        p.Discontinued\r\n    FROM Products p\r\n    INNER JOIN Categories c\r\n        ON p.CategoryID = c.CategoryID\r\n\r\n    WHERE\r\n    (\r\n        @ProductName IS NULL\r\n        OR p.ProductName LIKE '%' + @ProductName + '%'\r\n    )\r\n\r\n    AND\r\n    (\r\n        @CategoryName IS NULL\r\n        OR c.CategoryName LIKE '%' + @CategoryName + '%'\r\n    )\r\n\r\n    AND\r\n    (\r\n        @SupplierID IS NULL\r\n        OR p.SupplierID = @SupplierID\r\n    )\r\n\r\n    AND\r\n    (\r\n        @Discontinued IS NULL\r\n        OR p.Discontinued = @Discontinued\r\n    )\r\n\r\n    ORDER BY p.ProductID\r\n\r\n    OFFSET (@PageNumber - 1) * @PageSize ROWS\r\n    FETCH NEXT @PageSize ROWS ONLY\r\n\r\nEND\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_ListadoProductos' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_ObtenerProductoPorId]"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_ObtenerProductoPorId' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Objeto: StoredProcedure [dbo].[sp_ObtenerProductoPorId] Fecha de script: 9/05/2026 6:10:49 p. m. ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE PROCEDURE [dbo].[sp_ObtenerProductoPorId]\r\n(\r\n    @ProductID INT\r\n)\r\nAS\r\nBEGIN\r\n\r\n    SET NOCOUNT ON;\r\n\r\n    SELECT\r\n        p.ProductID,\r\n        p.ProductName,\r\n        p.SupplierID,\r\n        p.CategoryID,\r\n        c.CategoryName,\r\n        c.Picture,\r\n        p.QuantityPerUnit,\r\n        p.UnitPrice,\r\n        p.UnitsInStock,\r\n        p.UnitsOnOrder,\r\n        p.ReorderLevel,\r\n        p.Discontinued\r\n    FROM Products p\r\n    INNER JOIN Categories c\r\n        ON p.CategoryID = c.CategoryID\r\n    WHERE p.ProductID = @ProductID\r\n\r\nEND\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LAPTOP-ONQ147UB\\SQLEXPRESS']/Database[@Name='AsisyaDB']/StoredProcedure[@Name='sp_ObtenerProductoPorId' and @Schema='dbo']","object_type":"StoredProcedure"}}]}